if budget_path:
    print(f"Budget file path: {budget_path}")
else:
    raise ValueError("The 'budget_path' variable is not set.")

# Assuming budget_path is provided correctly

import openpyxl

# Load spreadsheet
wb = openpyxl.load_workbook(budget_path, data_only=True)
sheet = wb.active

# Extract data
budget = {}
for row in sheet.iter_rows(values_only=True):
    if row[0] and row[1] is not None:
        try:
            budget[str(row[0]).strip().lower()] = float(row[1])
        except:
            pass
